module flubber_optimizer (input clk, input rst_n, input start, input [31:0] v_fixed, input [31:0] a_fixed, input [5:0][31:0] c_edges, output done, output reg [31:0] f_best, output reg [31:0] w_best, output reg [31:0] val_best); reg [2:0] state; reg [3:0] index; reg [31:0] best_f, best_w, best_val, done_flag, current_f, current_w, best_val_temp; reg [63:0] left_side, right_side; wire [31:0] min_cap; assign min_cap = c_edges[0] < c_edges[1] ? c_edges[0] : c_edges[1]; assign min_cap = min_cap < c_edges[2] ? min_cap : c_edges[2]; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'b000; index <= 4'd0; best_f <= 32'd0; best_w <= 32'd0; best_val <= 32'd0; done_flag <= 1'b0; end else begin if (start) begin if (state == 3'b000) begin state <= 3'b001; index <= 4'd0; end end if (state == 3'b001) begin current_f = index << 16; current_w = (16 - index) << 16; left_side = (v_fixed * current_f) + (current_w << 16); right_side = ({32'd0, min_cap} << 16); if (left_side <= right_side) begin best_val_temp = (current_f * current_w) [31:0] + a_fixed; if (best_val_temp > best_val) begin best_f <= current_f; best_w <= current_w; best_val <= best_val_temp; end end if (index < 15) begin index <= index + 1; end else begin state <= 3'b010; done_flag <= 1'b1; end end end end end assign done = done_flag; assign f_best = best_f; assign w_best = best_w; assign val_best = best_val; endmodule